function cargarDatosGraficos(){const datosElement=document.getElementById("datos-graficos");if(datosElement)try{datosGraficos=JSON.parse(datosElement.textContent)}catch(e){console.error("Error al cargar datos de gráficos:",e);datosGraficos={}}document.readyState==="loading"?document.addEventListener("DOMContentLoaded",inicializarGraficos):inicializarGraficos()}function inicializarGraficos(){if(typeof Chart!="undefined"){if(datosGraficos.esProveedor){inicializarGraficoProveedorActividadMensual();inicializarGraficoProveedorActividadDiaria();inicializarGraficoProveedorDescargasFormato();return}inicializarGraficoActividadMensual();inicializarGraficoActividadDiaria();inicializarGraficoAccionesPorModulo()}}function inicializarGraficoProveedorActividadMensual(){const canvas=document.getElementById("graficoProveedorActividadMensual");canvas&&crearGraficoLinea(canvas,datosGraficos.actividadMensual||{},"rgb(75, 192, 192)","Actividades")}function inicializarGraficoProveedorActividadDiaria(){const canvas=document.getElementById("graficoProveedorActividadDiaria");canvas&&crearGraficoLinea(canvas,datosGraficos.actividadDiaria||{},"rgb(54, 162, 235)","Actividades")}function inicializarGraficoProveedorDescargasFormato(){const canvas=document.getElementById("graficoProveedorDescargasFormato");if(canvas){const datos=datosGraficos.descargasPorFormato||{},etiquetas=Object.keys(datos),valores=etiquetas.map(etiqueta=>datos[etiqueta]||0);new Chart(canvas,{type:"doughnut",data:{labels:etiquetas,datasets:[{data:valores,backgroundColor:["rgba(255, 99, 132, 0.8)","rgba(54, 162, 235, 0.8)","rgba(255, 206, 86, 0.8)","rgba(75, 192, 192, 0.8)"]}]},options:{responsive:!0,maintainAspectRatio:!0}})}}function crearGraficoLinea(canvas,datos,colorLinea,etiquetaDataset){const fechas=Object.keys(datos).sort(),valores=fechas.map(fecha=>datos[fecha]||0),fechasFormateadas=fechas.map(fecha=>{if(fecha.includes("-")&&fecha.length===10){const partes=fecha.split("-");return`${partes[2]}/${partes[1]}`}const partes=fecha.split("-");return partes.length>=2?`${partes[1]}/${partes[0]}`:fecha});new Chart(canvas,{type:"line",data:{labels:fechasFormateadas,datasets:[{label:etiquetaDataset,data:valores,borderColor:colorLinea,backgroundColor:"rgba(75, 192, 192, 0.2)",tension:.1,fill:!0}]},options:{responsive:!0,maintainAspectRatio:!0,scales:{y:{beginAtZero:!0,ticks:{precision:0}}}}})}function inicializarGraficoActividadMensual(){const canvas=document.getElementById("graficoActividadMensual");if(canvas){const datos=datosGraficos.actividadMensual||{},fechas=Object.keys(datos).sort(),valores=fechas.map(fecha=>datos[fecha]||0),fechasFormateadas=fechas.map(fecha=>{const[anio,mes]=fecha.split("-");return`${mes}/${anio}`});new Chart(canvas,{type:"line",data:{labels:fechasFormateadas,datasets:[{label:"Actividades",data:valores,borderColor:"rgb(75, 192, 192)",backgroundColor:"rgba(75, 192, 192, 0.2)",tension:.1,fill:!0}]},options:{responsive:!0,maintainAspectRatio:!0,plugins:{legend:{display:!0,position:"top"},tooltip:{mode:"index",intersect:!1}},scales:{y:{beginAtZero:!0,ticks:{precision:0}}}}})}}function inicializarGraficoActividadDiaria(){const canvas=document.getElementById("graficoActividadDiaria");if(canvas){const datos=datosGraficos.actividadDiaria||{},fechas=Object.keys(datos).sort(),valores=fechas.map(fecha=>datos[fecha]||0),fechasFormateadas=fechas.map(fecha=>{const[,mes,dia]=fecha.split("-");return`${dia}/${mes}`});new Chart(canvas,{type:"line",data:{labels:fechasFormateadas,datasets:[{label:"Actividades",data:valores,borderColor:"rgb(54, 162, 235)",backgroundColor:"rgba(54, 162, 235, 0.2)",tension:.1,fill:!0,pointRadius:4,pointHoverRadius:6}]},options:{responsive:!0,maintainAspectRatio:!0,plugins:{legend:{display:!0,position:"top"},tooltip:{mode:"index",intersect:!1}},scales:{y:{beginAtZero:!0,ticks:{precision:0}}}}})}}function inicializarGraficoAccionesPorModulo(){const canvas=document.getElementById("graficoAccionesPorModulo");if(canvas){const datos=datosGraficos.accionesPorModulo||{},modulos=Object.keys(datos),valores=modulos.map(modulo=>datos[modulo]||0),colores=["rgba(255, 99, 132, 0.8)","rgba(54, 162, 235, 0.8)","rgba(255, 206, 86, 0.8)","rgba(75, 192, 192, 0.8)","rgba(153, 102, 255, 0.8)","rgba(255, 159, 64, 0.8)"];new Chart(canvas,{type:"bar",data:{labels:modulos,datasets:[{label:"Acciones",data:valores,backgroundColor:modulos.map((_,i)=>colores[i%colores.length]),borderColor:modulos.map((_,i)=>colores[i%colores.length].replace("0.8","1")),borderWidth:1}]},options:{responsive:!0,maintainAspectRatio:!0,plugins:{legend:{display:!1},tooltip:{mode:"index",intersect:!1}},scales:{y:{beginAtZero:!0,ticks:{precision:0}}}}})}}let datosGraficos={};document.readyState==="loading"?document.addEventListener("DOMContentLoaded",cargarDatosGraficos):cargarDatosGraficos();